// Validates the enquiry from aventos.marvice.tech, re-scores it on the server
// (the browser's score can't be trusted) and flattens it into one sheet row.
const b = $json.body || {};
const h = $json.headers || {};
const s = (v, n = 300) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, n);
const c = b.contact || {}, needs = b.needs || {}, a = b.attribution || {}, ft = a.firstTouch || {}, e = b.engagement || {};

// Honeypot: bots fill the hidden "website" field. Accept silently, store nothing.
if (s(b.website)) return [{ json: { _valid: false, _spam: true } }];

const errors = [];
if (JSON.stringify(b).length > 20000) errors.push('payload too large');
if (!['individual', 'fleet', 'dealer'].includes(b.type)) errors.push('type');
if (s(c.name).length < 2) errors.push('name');
const phone = s(c.phone, 20).replace(/\D/g, '').slice(-10);
if (!/^[6-9]\d{9}$/.test(phone)) errors.push('phone');
const pincode = s(c.pincode, 6);
if (!/^[1-9]\d{5}$/.test(pincode)) errors.push('pincode');
const email = s(c.email, 120);
if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errors.push('email');
if (c.consent !== true) errors.push('consent');
if (errors.length) return [{ json: { _valid: false, _errors: errors } }];

// Server-side priority score (same rules as the site)
let score = 0;
score += { 'This month': 40, 'Within 3 months': 35, '1–3 months': 25, '3–6 months': 12 }[needs.timeline] || 0;
if (b.type === 'fleet') score += { '1–10': 10, '11–50': 25, '51–200': 40, '200+': 50 }[needs.fleetSize] || 0;
if (b.type === 'dealer') score += { '₹10–25 lakh': 10, '₹25–50 lakh': 25, '₹50 lakh+': 40 }[needs.investment] || 0;
if (b.type === 'individual') { if (needs.payment) score += 10; if (c.testRide) score += 10; if (needs.model && needs.model !== 'Not sure') score += 5; }
if (email) score += 5;
const grade = score >= 50 ? 'Hot' : score >= 25 ? 'Warm' : 'Nurture';

const typeLabel = { individual: 'Purchase & test ride', fleet: 'Fleet enquiry', dealer: 'Dealership' }[b.type];
const company = s(needs.company || needs.business, 120);
const details = Object.entries(needs)
  .filter(([k, v]) => v !== '' && !(Array.isArray(v) && !v.length) && !['company', 'business', 'model', 'timeline'].includes(k))
  .map(([k, v]) => `${k}: ${Array.isArray(v) ? v.map(x => s(x, 60)).join(', ') : s(v, 120)}`).join(' | ');
const ref = /^AE-[A-Z0-9]{4,10}$/.test(b.ref) ? b.ref : 'AE-' + Date.now().toString(36).toUpperCase().slice(-6);
const phoneFmt = `+91 ${phone.slice(0, 5)} ${phone.slice(5)}`;

const row = {
  'Received (IST)': new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
  'Ref': ref,
  'Type': typeLabel,
  'Priority': grade,
  'Score': score,
  'Name': s(c.name, 80),
  'Phone': phoneFmt,
  'Email': email,
  'Pincode': pincode,
  'Contact via': s(c.channel, 30),
  'Best time': s(c.bestTime, 30),
  'Test ride': c.testRide ? 'Yes' : 'No',
  'Model': s(needs.model, 30),
  'Timeline': s(needs.timeline, 30),
  'Company / Business': company,
  'Details': details,
  'Source channel': s(ft.channel, 40),
  'Source': s(ft.source, 120),
  'Campaign': s(ft.campaign, 120),
  'Landing page': s(ft.landing, 200),
  'Visits': Number(a.visits) || 1,
  'Seconds on site': Number(e.secondsOnSite) || 0,
  'Sections viewed': Array.isArray(e.sectionsViewed) ? e.sectionsViewed.map(x => s(x, 30)).join(', ') : '',
  'Status': 'New',
};

const icon = { Hot: '🔥', Warm: '🟡', Nurture: '⚪' }[grade];
const line2 = b.type === 'fleet' ? `${company} · ${needs.fleetSize} vehicles · ${needs.industry}`
  : b.type === 'dealer' ? `${company} · ${s(needs.dealerCity, 60)} · ${needs.investment}`
  : `${row.Model} · ${row['Test ride'] === 'Yes' ? 'wants a test ride' : 'no test ride'}`;
const alert = [
  `${icon} ${grade.toUpperCase()} lead · ${typeLabel}`,
  `${row.Name} · ${phoneFmt}${email ? ' · ' + email : ''}`,
  line2,
  `Timeline: ${row.Timeline || '—'} · Pincode ${pincode}`,
  `Reach via ${row['Contact via']} (${row['Best time']})`,
  `Source: ${row['Source channel']} (${row.Source})`,
  `Ref ${ref}`,
].join('\n');

return [{ json: { ...row, _valid: true, _alert: alert, _ip: s(h['cf-connecting-ip'] || h['x-real-ip'], 45) } }];

